import {ToolRegistry} from './registry.js';

describe('Dynamic schema cache [spec: specs/hal-engine-tool-input-validation/spec.md#9]', () => {
  it('reuses a dynamic schema without reading it again', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const inputSchema = {
      get "'$id() {
        schemaReads++;
        return '"'https://example.com/location';
      },
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({name: 'echo', description: 'Echo a location', inputSchema}),
      async input => JSON.stringify(input)
    );
    const input = {location: 'Berlin'};
    await registry.execute('echo', input);
    const initialReads = schemaReads;

    const response = await registry.execute('echo', input);

    expect({response, schemaReads}).toEqual({response: {result: JSON.stringify(input)}, schemaReads: initialReads});
  });
});
EOF
